/*
Theme Name: Browser Directory
Version: 1.0
*/
* { box-sizing: border-box }
html { background: #f8f6ee }
body { margin: 0; color: #172a23; background: #f8f6ee; font: 1.05rem/1.55 system-ui,sans-serif }
main { max-width: 69rem; margin: auto; padding: 2rem clamp(1.3rem,5vw,5rem) 5rem }
.mast { border-bottom: 2px solid; padding-bottom: 1rem; font-weight: 650 }
h1,h2 { font-family: Georgia,serif; font-weight: 400; line-height: 1.07; text-wrap: balance }
h1 { font-size: clamp(3.25rem,8vw,7rem); letter-spacing: -.055em; margin: .48em 0 .25em }
.intro { max-width: 45rem; font-size: clamp(1.15rem,2.3vw,1.55rem); margin: 0 0 2.5rem }
h2 { margin: 0 0 .35em; font-size: clamp(2rem,4.5vw,3.4rem); letter-spacing: -.04em }
.group { padding: 2rem 0; border-top: 1px solid #98a599 }
.group-intro { margin: .25rem 0 1.5rem; max-width: 45rem }
ul.projects { list-style: none; padding: 0; margin: 0; display: grid; grid-template-columns: repeat(auto-fit,minmax(min(100%,16rem),1fr)); gap: 1.2rem 2.2rem }
.projects li { margin: 0 }
a { color: #115c44; text-decoration-thickness: 1px; text-underline-offset: .2em }
a:focus-visible { outline: 3px solid #115c44; outline-offset: 4px }
a:hover { color: #082e23; text-decoration-thickness: 2px }
.projects a { font-weight: 700; font-size: 1.19rem }
.projects li span { display: block; font-size: .96rem; color: #374c42; margin-top: .2rem }
.projects a.project-name { display:inline-flex; align-items:center; gap:.5rem; }
.projects a.project-name::before { content:""; width:1.5rem; height:1.5rem; flex:none; background:var(--project-mark) center / contain no-repeat; }
.projects .source-link { display:inline-block; margin-top:.25rem; font-size:.85rem; font-weight:500; }

